//! Admin CRUD over the three tables, generated by viewset.
//!
//! Each row type derives `viewset::Entity`; one generic [`PgRepo`] serves all
//! of them and `DefaultService` / `DefaultViewSet` supply the
//! list/retrieve/create/update/delete routes, mounted under
//! `/{namespace}/admin/{accounts,credits,processed-debits}`.
//!
//! These viewsets deliberately bypass [`crate::service::PaymentService`]: they
//! are for administrators to browse and correct raw rows. Creating a `Credit`
//! does **not** touch `accounts.balance`, and creating a `ProcessedDebit` does
//! not deduct anything or emit `payment.debit.success`. Use `POST /credit` and
//! the `payment.debit.request` event for real money movement.
//!
//! Access control is ferrumec's permission middleware, driven by
//! `permissions.json` (see the README) — keep that file in step with the routes
//! here, because a route with no entry is **not** protected.
//!
//! No caches are configured. The domain code updates these tables with raw SQL,
//! so any viewset item/list cache would serve stale balances and ledger rows.

use std::marker::PhantomData;
use std::sync::Arc;

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use sqlx::{FromRow, PgPool};
use uuid::Uuid;
use viewset::web::DefaultService;
use viewset::{DefaultViewSet, Entity, Repository};

// ============ Account ============

/// A user's balance row (table `accounts`). `id` is the user's id — one row
/// per user. It may be set on create but never changed afterwards.
#[derive(Entity, Debug, Clone, Serialize, Deserialize, FromRow)]
#[entity(create = "CreateAccount", update = "UpdateAccount")]
pub struct Account {
    #[entity(skip_update)]
    pub id: Uuid,
    pub balance: i64,
}

/// Payload for `POST /admin/accounts`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CreateAccount {
    pub id: Uuid,
    #[serde(default)]
    pub balance: i64,
}

/// Payload for `PUT/PATCH /admin/accounts/{id}`. Only `balance` may change;
/// correcting it directly bypasses the credit ledger, so use with care.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct UpdateAccount {
    pub balance: Option<i64>,
}

// ============ Credit ============

/// An append-only credit ledger row (table `credits`); no update route.
#[derive(Entity, Debug, Clone, Serialize, Deserialize, FromRow)]
#[entity(create = "CreateCredit")]
pub struct Credit {
    #[entity(skip_create)]
    pub id: Uuid,
    pub user_id: Uuid,
    pub amount: i64,
    #[entity(skip_create)]
    pub created: DateTime<Utc>,
}

/// Payload for `POST /admin/credits` (record correction only, see module docs).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CreateCredit {
    pub user_id: Uuid,
    pub amount: i64,
}

// ============ ProcessedDebit ============

/// A settled-debit idempotency record (table `processed_debits`); `id` is the
/// caller-supplied `debit_id`. No update route.
#[derive(Entity, Debug, Clone, Serialize, Deserialize, FromRow)]
#[entity(create = "CreateProcessedDebit")]
pub struct ProcessedDebit {
    pub id: Uuid,
    pub order_id: Uuid,
    pub user_id: Uuid,
    pub amount: i64,
    #[entity(skip_create)]
    pub created: DateTime<Utc>,
}

/// Payload for `POST /admin/processed-debits` (record correction only).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CreateProcessedDebit {
    pub id: Uuid,
    pub order_id: Uuid,
    pub user_id: Uuid,
    pub amount: i64,
}

// ============ Generic wiring ============

/// Uncached viewset repository for any [`Entity`].
pub struct PgRepo<E: Entity> {
    pool: PgPool,
    _entity: PhantomData<fn() -> E>,
}

impl<E: Entity> PgRepo<E> {
    pub fn new(pool: PgPool) -> Self {
        Self {
            pool,
            _entity: PhantomData,
        }
    }
}

impl<E: Entity> Repository for PgRepo<E> {
    type Entity = E;

    fn database(&self) -> &PgPool {
        &self.pool
    }
}

/// The generic CRUD viewset for `E`.
pub type AdminViewSet<E> = DefaultViewSet<DefaultService<PgRepo<E>>>;

/// Builds the admin viewset for `E` over `pool`.
pub fn admin_viewset<E: Entity>(pool: PgPool) -> Arc<AdminViewSet<E>> {
    Arc::new(DefaultService(PgRepo::<E>::new(pool)).into())
}
